"""
top_image.py - يرسم صورة توب القروبات فوق القالب الجاهز.

القالب والخطوط مدمجين داخل هذا الملف (آخر الملف) فما تحتاج مجلد assets ولا أي ملف ثاني.
لو حبيت تغير القالب أو الخط بعدين، حط ملفات بنفس هذي الأسماء وهي تتقدم على المدمج:
    assets/top_groups.png
    assets/font_bold.ttf
    assets/font_regular.ttf
"""

import base64
import io
import os
from functools import lru_cache
from typing import Optional

import arabic_reshaper
from PIL import Image, ImageDraw, ImageFont

try:
    from bidi import get_display
except ImportError:  # نسخ python-bidi القديمة
    from bidi.algorithm import get_display

TEMPLATE_PATH = "assets/top_groups.png"
FONT_BOLD = "assets/font_bold.ttf"
FONT_REG = "assets/font_regular.ttf"

# المقاس الأساسي اللي قست عليه الإحداثيات
BASE_W, BASE_H = 1672, 941

# (x1, y1, x2, y2) لكل مركز - عدّلها لو احتجت ضبط دقيق
SLOTS = [
    (595, 337, 1077, 603),    # 1
    (128, 380, 572, 600),     # 2
    (1102, 380, 1546, 600),   # 3
    (124, 645, 324, 808),     # 4
    (350, 645, 551, 808),     # 5
    (577, 645, 776, 808),     # 6
    (803, 645, 1030, 808),    # 7
    (1058, 645, 1274, 808),   # 8
    (1302, 645, 1550, 808),   # 9
]

# ألوان
WHITE = (255, 255, 255, 255)
SOFT = (200, 190, 240, 255)
GOLD = (255, 224, 140, 255)
SHADOW = (20, 10, 50, 255)


def ar(text: str) -> str:
    """تجهيز النص العربي للرسم (وصل الحروف + اتجاه صحيح)."""
    return get_display(arabic_reshaper.reshape(str(text)))


# ---------------------------------------------------------------- الأصول المدمجة
@lru_cache(maxsize=None)
def _decoded(name: str) -> bytes:
    return base64.b64decode(_EMBEDDED[name])


@lru_cache(maxsize=128)
def _font(path: str, size: int) -> ImageFont.FreeTypeFont:
    if os.path.exists(path):
        return ImageFont.truetype(path, size)
    if path in _EMBEDDED:
        return ImageFont.truetype(io.BytesIO(_decoded(path)), size)
    return ImageFont.load_default()


def _load_template() -> Image.Image:
    if os.path.exists(TEMPLATE_PATH):
        img = Image.open(TEMPLATE_PATH)
    else:
        img = Image.open(io.BytesIO(_decoded(TEMPLATE_PATH)))
    return img.convert("RGBA")


# ---------------------------------------------------------------- الرسم
def _fit_text(draw, text, path, start_size, max_width, min_size=14):
    """يصغّر الخط تلقائياً لين يدخل النص بعرض المربع."""
    size = start_size
    while size > min_size:
        font = _font(path, size)
        box = draw.textbbox((0, 0), text, font=font)
        if box[2] - box[0] <= max_width:
            return font
        size -= 2
    return _font(path, min_size)


def _circle_logo(data: Optional[bytes], size: int) -> Optional[Image.Image]:
    if not data:
        return None
    try:
        img = Image.open(io.BytesIO(data)).convert("RGBA").resize((size, size), Image.LANCZOS)
    except Exception:
        return None
    mask = Image.new("L", (size, size), 0)
    ImageDraw.Draw(mask).ellipse((0, 0, size - 1, size - 1), fill=255)
    out = Image.new("RGBA", (size, size), (0, 0, 0, 0))
    out.paste(img, (0, 0), mask)
    return out


def _centered(draw, cx, y, text, font, fill):
    box = draw.textbbox((0, 0), text, font=font)
    w = box[2] - box[0]
    draw.text(
        (cx - w / 2, y), text, font=font, fill=fill,
        stroke_width=2, stroke_fill=SHADOW,
    )
    return box[3] - box[1]


def _draw_slot(canvas, draw, rect, rank, group):
    x1, y1, x2, y2 = rect
    w, h = x2 - x1, y2 - y1
    cx = (x1 + x2) // 2
    big = rank <= 3

    # مساحة فوق لتاج المركز، ثم: لوقو -> اسم -> نقاط
    pad = int(h * (0.27 if rank == 1 else 0.21 if big else 0.16))
    logo_size = int(h * (0.30 if big else 0.27))
    gap = max(6, int(h * 0.035))
    y = y1 + pad

    logo = _circle_logo(group.get("logo"), logo_size)
    if logo:
        canvas.paste(logo, (cx - logo_size // 2, y), logo)
        draw.ellipse(
            (cx - logo_size // 2, y, cx + logo_size // 2, y + logo_size),
            outline=GOLD if rank == 1 else SOFT, width=3,
        )
        y += logo_size + gap
    else:
        y += int(logo_size * 0.35)

    name = ar(group["name"])
    name_font = _fit_text(draw, name, FONT_BOLD, 42 if rank == 1 else 36 if big else 25, w - 30)
    name_bottom = draw.textbbox((0, 0), name, font=name_font)[3]
    _centered(draw, cx, y, name, name_font, WHITE)
    y += name_bottom + gap

    pts = ar(f"{group['points']:,} نقطة")
    pts_font = _fit_text(draw, pts, FONT_REG, 30 if rank == 1 else 26 if big else 19, w - 30)
    _centered(draw, cx, y, pts, pts_font, GOLD if rank == 1 else SOFT)


def render_top(groups: list, footer: Optional[str] = None) -> io.BytesIO:
    """
    groups: قائمة مرتبة من الأعلى للأقل، كل عنصر:
        {"name": str, "points": int, "logo": bytes | None}
    footer: نص صغير يظهر أسفل الصورة بالمنتصف (اختياري)
    ترجع BytesIO جاهز لـ discord.File
    """
    canvas = _load_template()
    sx, sy = canvas.width / BASE_W, canvas.height / BASE_H
    draw = ImageDraw.Draw(canvas)

    for i, group in enumerate(groups[: len(SLOTS)]):
        x1, y1, x2, y2 = SLOTS[i]
        rect = (int(x1 * sx), int(y1 * sy), int(x2 * sx), int(y2 * sy))
        _draw_slot(canvas, draw, rect, i + 1, group)

    if footer:
        text = ar(footer)
        font = _fit_text(draw, text, FONT_REG, 24, int(canvas.width * 0.3))
        _centered(draw, canvas.width // 2, int(866 * sy), text, font, SOFT)

    buf = io.BytesIO()
    canvas.save(buf, "PNG", optimize=True)
    buf.seek(0)
    return buf


def debug_slots() -> io.BytesIO:
    """يرسم إطار أحمر وأرقام على كل مربع للتأكد من الإحداثيات."""
    canvas = _load_template()
    sx, sy = canvas.width / BASE_W, canvas.height / BASE_H
    draw = ImageDraw.Draw(canvas)
    font = _font(FONT_BOLD, 40)
    for i, (x1, y1, x2, y2) in enumerate(SLOTS, 1):
        r = (int(x1 * sx), int(y1 * sy), int(x2 * sx), int(y2 * sy))
        draw.rectangle(r, outline=(255, 0, 0, 255), width=4)
        draw.text((r[0] + 10, r[1] + 10), str(i), font=font, fill=(255, 0, 0, 255))
    buf = io.BytesIO()
    canvas.save(buf, "PNG")
    buf.seek(0)
    return buf


